			// that reads it is the fp16 one.
			qkvTail: uint32((i*perBank + qkvBank) / 2),
			out:     uint32((i*perBank + qkvBank + tailBank) / unit),
			conv:    base,
			gamma:   base + uint32(cw*c.Conv),
